def test_tickets_incidents_activation_dry_run_result_contract_requires_request_context() -> None:
    response = client.post(
        "/v1/platform/modules/families/tickets-incidents/activation-dry-run-result-contract",
        json={
            "activation_dry_run_plan_evidence_hash": "sha256:" + "0" * 64,
            "activation_dry_run_execution_boundary_evidence_hash": "sha256:" + "1" * 64,
            "activation_dry_run_execution_skeleton_evidence_hash": "sha256:" + "2" * 64,
            "activation_dry_run_executor_implementation_review_evidence_hash": "sha256:" + "3" * 64,
            "activation_execution_boundary_evidence_hash": "sha256:" + "4" * 64,
            "activation_executor_skeleton_evidence_hash": "sha256:" + "5" * 64,
            "tenant_admin_approval_gate_hash": "sha256:" + "6" * 64,
            "tenant_admin_approval_record_hash": "sha256:" + "7" * 64,
            "activation_dry_run_result_contract_ref": "tickets-activation-dry-run-result-contract:missing-context",
            "change_request_ref": "change:tickets-activation-dry-run-result-contract-missing-context",
            "idempotency_key_ref": "idempotency:tickets-activation-dry-run-result-contract-missing-context",
            "prepared_at_utc": "2026-07-09T08:35:00Z",
            "audit_chain_ref": "audit:tickets-activation-dry-run-result-contract-missing-context",
            "activation_dry_run_result_contract_statement": (
                TICKETS_INCIDENTS_ACTIVATION_DRY_RUN_RESULT_CONTRACT_STATEMENT
            ),
        },
    )

    assert response.status_code == 401
    assert response.json()["detail"] == "Tenant context requires X-Tenant-Id and X-User-Id headers"


