def test_platform_cockpit_mvp_pilot_decision_record_schema_requires_request_context() -> None:
    response = client.get("/v1/platform/cockpit/mvp-pilot-decision-record-schema")

    assert response.status_code == 401
    assert response.json()["detail"] == "Tenant context requires X-Tenant-Id and X-User-Id headers"


